'use client';
import { useRouter } from 'next/navigation';
import { startTransition } from 'react';

export default function Error({ error, reset }: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  const router = useRouter();
  const retry = () => startTransition(() => {
    router.refresh(); // refetch server data...
    reset();          // ...then re-render the boundary
  });
  return (
    <div>
      <p>Something went wrong. (ref: {error.digest})</p>
      <button onClick={retry}>Try again</button>
    </div>
  );
}

// middleware.ts
import { NextResponse, type NextRequest } from 'next/server';
import { verifyJwt } from '@/lib/jwt'; // jose-based, Edge-compatible

const PROTECTED = ['/dashboard', '/settings'];

export async function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;
  const token = req.cookies.get('session')?.value;
  const valid = token ? await verifyJwt(token) : null; // signature check only

  if (PROTECTED.some(p => pathname.startsWith(p)) && !valid) {
    const login = new URL('/login', req.url);
    login.searchParams.set('from', pathname); // relative path only!
    return NextResponse.redirect(login);
  }
  if (pathname === '/login' && valid) {
    return NextResponse.redirect(new URL('/dashboard', req.url));
  }
  return NextResponse.next();
}

