// 2. Webhook: app/api/revalidate/route.ts
import { revalidateTag } from 'next/cache';
export async function POST(req: Request) {
  if (req.headers.get('x-secret') !== process.env.REVALIDATE_SECRET)
    return new Response('Unauthorized', { status: 401 });
  const { tag } = await req.json();
  revalidateTag(tag);              // server caches only
  return Response.json({ ok: true });
}

// 3. Server Action after a mutation
export async function updatePost(id: string, data: PostInput) {
  'use server';
  await db.post.update({ where: { id }, data });
  revalidateTag(`post-${id}`);     // server caches + THIS user's router cache
}

